import {createScorePages,scorePDF,printSettings,parseBreaks} from './score-pages.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showPrintDialog({project,part,modal,download,saveSettings}){
 const initial=printSettings(project);let layout=null,working=false;
 modal('Print & PDF',`<div class="print-workspace"><aside class="print-controls"><label>Score<select id="print-part"><option value="">Full ensemble score</option>${project.tracks.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></label><label>Paper<select id="print-paper"><option value="letter">US Letter</option><option value="a4">A4</option></select></label><label>Staff size<select id="print-scale"><option value="0.8">Compact</option><option value="1">Standard</option><option value="1.2">Large</option><option value="1.4">Extra large</option></select></label><label>Measures per line<select id="print-measures"><option value="4">Four</option><option value="2">Two</option><option value="1">One</option><option value="auto">Automatic</option></select></label><label class="checkbox-label"><input id="print-names" type="checkbox">Show note names</label><label class="checkbox-label"><input id="print-inactive" type="checkbox">Hide inactive ensemble staves</label><details><summary>Line & page breaks</summary><label>Start a new line at measures<input id="print-lines" placeholder="5, 9, 13"></label><label>Start a new page at measures<input id="print-breaks" placeholder="9, 17"></label><p>Use numbers from the music selected for this preview.</p></details><button class="outline" id="print-refresh">Update preview</button><button class="brass" id="print-pdf">Download PDF</button><p id="print-status" role="status" aria-live="polite"></p><p class="practice-hint">The PDF uses these exact page breaks. Open the downloaded PDF to print it at actual size.</p></aside><div class="print-preview" aria-label="Print page preview"></div></div>`);
 const root=document.querySelector('.print-workspace'),$=s=>root.querySelector(s),preview=$('.print-preview');
 $('#print-part').value=part||'';$('#print-paper').value=initial.paper;$('#print-scale').value=initial.staffScale;$('#print-measures').value=part?initial.partMeasures:initial.teacherMeasures;$('#print-names').checked=!!initial.noteNames;$('#print-inactive').checked=initial.hideInactiveStaves!==false;$('#print-lines').value=(initial.lineBreaks||[]).join(', ');$('#print-breaks').value=(initial.pageBreaks||[]).join(', ');
 const update=()=>{try{const selected=$('#print-part').value,measures=$('#print-measures').value;const settings={...printSettings(project),paper:$('#print-paper').value,staffScale:+$('#print-scale').value,noteNames:$('#print-names').checked,hideInactiveStaves:$('#print-inactive').checked,lineBreaks:parseBreaks($('#print-lines').value,project.bars),pageBreaks:parseBreaks($('#print-breaks').value,project.bars),[selected?'partMeasures':'teacherMeasures']:measures==='auto'?'auto':+measures};layout=createScorePages(project,{part:selected||null,settings});project.notation={...project.notation,...settings};saveSettings(settings);preview.replaceChildren(...layout.pages.map((svg,i)=>{const page=document.createElement('figure');page.className='print-page';page.append(svg);const caption=document.createElement('figcaption');caption.textContent='Page '+(i+1)+' of '+layout.pages.length;page.append(caption);return page;}));$('#print-status').textContent=layout.pages.length+' page'+(layout.pages.length===1?'':'s')+'. '+layout.warnings.join(' ');$('#print-pdf').disabled=false;return true;}catch(e){layout=null;$('#print-status').textContent=e.message;$('#print-pdf').disabled=true;return false;}};
 $('#print-refresh').onclick=update;root.querySelectorAll('input,select').forEach(el=>el.onchange=()=>{if(!working)update();});
 $('#print-pdf').onclick=async()=>{if(working||!update())return;working=true;root.querySelectorAll('button,input,select').forEach(e=>e.disabled=true);try{const blob=await scorePDF(layout,{onProgress:n=>$('#print-status').textContent='Preparing PDF · '+Math.round(n*100)+'%'});download(blob,project.title.replace(/[^a-z0-9-]/gi,'-')+($('#print-part').value?'-part':'-score')+'.pdf');$('#print-status').textContent='PDF downloaded. Open it to print.';}catch(e){$('#print-status').textContent='PDF could not be prepared: '+e.message;}finally{working=false;root.querySelectorAll('button,input,select').forEach(e=>e.disabled=false);}};
 update();
}
